css:
@font-face{font-family:'Barlow Condensed';font-weight:800;font-style:normal;font-display:block;src:url('assets/fonts/BarlowCondensed-800-normal.woff2')}
/* Tipografía B: titles with a soft neon glow. Colour: .cine-title (white), .cine-title.y (#FFF238), or style='--c:#hex;--g:<hex at .7>;--g2:<hex at .35>' */
.cine-title{--c:#FFFFFF;--g:rgba(255,255,255,.7);--g2:rgba(255,255,255,.35);position:absolute;left:0;width:1080px;text-align:center;
  font-family:'Barlow Condensed';font-weight:800;text-transform:uppercase;font-size:97px;line-height:.98;letter-spacing:-.015em;
  color:var(--c);text-shadow:0 0 6px var(--g),0 0 18px var(--g),0 0 36px var(--g2);filter:blur(.3px)}
.cine-title.y{--c:#FFF238;--g:rgba(255,242,56,.75);--g2:rgba(255,242,56,.4)}
.cine-title .ln{display:block;margin:0 auto;max-width:766px}
/* the black gradient behind every title, from the top edge down past the title */
.cine-grad{position:absolute;left:0;top:0;width:1080px;height:760px;
  background:linear-gradient(to bottom,rgba(0,0,0,.78) 0%,rgba(0,0,0,.55) 38%,rgba(0,0,0,0) 100%)}
/* H2: DM Serif Display italic with the same soft neon glow as the H1 (yellow by default; .w = white; any colour with
   style='--c:#hex;--g:<hex at .7>;--g2:<hex at .35>'). Sits with an H1, e.g. a kicker line above it. */
.cine-h2{--c:#FFF238;--g:rgba(255,242,56,.7);--g2:rgba(255,242,56,.35);position:absolute;left:0;width:1080px;text-align:center;
  font-family:'DM Serif Display';font-weight:400;font-style:italic;font-size:80px;line-height:1;letter-spacing:-.01em;
  color:var(--c);text-shadow:0 0 6px var(--g),0 0 18px var(--g),0 0 36px var(--g2);filter:blur(.3px)}
.cine-h2.w{--c:#FFFFFF;--g:rgba(255,255,255,.7);--g2:rgba(255,255,255,.35)}
.cine-h2 .r{font-style:normal}
